import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import * as fontkit from 'fontkit'
import { describe, expect, it } from 'vitest'

/**
 * WHAT THE SHIPPED CJK SUBSET COVERS.
 *
 * The UI is English; the Chinese in this font is for what the PERSON types -- a task title, a
 * note. The subset is generated by hand (`tools/fonts/subset-cjk-font.py`) and committed, because
 * the Docker build runs on `node:24-alpine` and has no Python, so nothing in CI regenerates it and
 * nothing but this file notices if it is rebuilt to a narrower budget. The coverage is read out of
 * the SHIPPED woff2's own cmap, never out of a list that claims to describe it.
 *
 * READING THE CMAP IS `fontkit`'S JOB, not ours: it reads woff2, Brotli and cmap formats
 * 0/4/6/12/13/14, where a hand-written reader would have to know which format a newer fontTools
 * emits.
 *
 * `hasGlyphForCodePoint`, not `characterSet` alone: the two differ by exactly one codepoint on this
 * font. A format-4 cmap must end with a segment mapping U+FFFF to glyph 0 (the missing glyph), and
 * `characterSet` enumerates the declared ranges without checking where they LAND -- so it reports
 * 6880 where the real coverage is 6879. Letting that through would quietly widen what counts as
 * "covered", which is the one thing this file must not do.
 */
const here = dirname(fileURLToPath(import.meta.url))
const font = readFileSync(join(here, 'noto-sans-sc-subset.woff2'))
// `create` answers `Font | FontCollection`; this file is a single-face woff2, and narrowing to the
// real `Font` type is what gives `characterSet` and `hasGlyphForCodePoint` their own signatures
// rather than a structural guess written here.
const face = fontkit.create(font) as fontkit.Font
const covered = new Set(face.characterSet.filter((code) => face.hasGlyphForCodePoint(code)))

describe('the self-hosted CJK subset', () => {
  it('covers what a user types', () => {
    // Four han that appear in real task titles. A subset cut to the UI's own vocabulary omits
    // them, and because font fallback is per glyph that would draw one task title in two faces at
    // two weights. If this test fails, someone has narrowed the character budget; see styles.css.
    for (const char of '简舍练习') {
      expect(covered.has(char.codePointAt(0)!), `${char} is not in the subset`).toBe(true)
    }
    // GB2312 level 1 + 2 is 6,763 han; with Latin and GB2312's own punctuation rows the budget is
    // 7,049 codepoints. The floor is just under that on purpose: a han-only rebuild lands at 6,869
    // and must fail here rather than pass by 300.
    expect(covered.size).toBeGreaterThan(7000)
  })

  it('covers the marks a Chinese sentence is made of', () => {
    // Not han, and not in the han rows the budget is mostly made of. The UI's copy is English, so
    // only an explicit punctuation budget keeps them in the subset; without it a typed title takes
    // its commas and brackets from a fallback face, per glyph, mid-sentence.
    for (const char of '、。，；：？！「」『』（）《》【】…—·～') {
      expect(covered.has(char.codePointAt(0)!), `${char} is not in the subset`).toBe(true)
    }
  })

  /**
   * The one place the library's answer is not taken as given. A codepoint whose cmap entry points at the
   * missing glyph is not covered -- drawing it would draw a blank box, or fall back to another face,
   * which is precisely the failure the two tests above exist to catch. U+FFFF is where a format-4
   * cmap always has such an entry, by the spec's own requirement, so it is the case to pin.
   */
  it('does not count a codepoint the cmap maps to the missing glyph', () => {
    expect(face.characterSet).toContain(0xffff)
    expect(face.hasGlyphForCodePoint(0xffff)).toBe(false)
    expect(covered.has(0xffff)).toBe(false)
    expect(covered.size).toBe(face.characterSet.length - 1)
  })
})
